package com.muxigame.city;
import java.util.*;
import net.minecraft.core.BlockPos;
import net.minecraft.gametest.framework.*;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.world.level.block.Blocks;
import net.neoforged.neoforge.gametest.*;
@GameTestHolder(CityMod.ID) @PrefixGameTestTemplate(false)
public final class CityTestsHunters {
 public static final class HomeAI {public boolean returnToStart=true;}
 public static final class ReturnGoalPig extends net.minecraft.world.entity.animal.Pig {
  public final HomeAI ais=new HomeAI();public ReturnGoalPig(net.minecraft.world.level.Level level){super(net.minecraft.world.entity.EntityType.PIG,level);}
 }
 @GameTest(template="empty") public static void hunterReturnGoalRestoresPriorSetting(GameTestHelper h){var mob=new ReturnGoalPig(h.getLevel());HunterForest.reconcileHome(mob,true);h.assertTrue(!mob.ais.returnToStart,"Hunter owns patrol navigation");HunterForest.reconcileHome(mob,true);HunterForest.reconcileHome(mob,false);h.assertTrue(mob.ais.returnToStart,"Original return flag survives repeated ticks");mob.ais.returnToStart=false;HunterForest.reconcileHome(mob,true);HunterForest.reconcileHome(mob,false);h.assertTrue(!mob.ais.returnToStart,"Preserves initially disabled return flag");h.succeed();}
 @GameTest(template="empty") public static void trunkSampleFindsSafeAdjacentGround(GameTestHelper h){for(int x=0;x<3;x++)for(int z=0;z<3;z++){h.setBlock(x,1,z,Blocks.STONE);h.setBlock(x,4,z,Blocks.OAK_LEAVES);}h.setBlock(1,2,1,Blocks.OAK_LOG);var canopy=h.absolutePos(new BlockPos(1,4,1));var stand=HunterForest.findStand(h.getLevel(),canopy);h.assertTrue(stand!=null&&stand.getY()==h.absolutePos(new BlockPos(0,2,0)).getY()&&!stand.equals(h.absolutePos(new BlockPos(1,2,1))),"Canopy sampled over trunk finds adjacent ground, never a far lower unwooded column");h.succeed();}
 @GameTest(template="empty") public static void workAndOvertime(GameTestHelper h){var c=new WorkHours.Config();c.willingness=100;h.assertTrue(WorkHours.allowed(c,0,60,0)&&!WorkHours.allowed(c,12000,60,0),"High stability allows day, forbids night");h.assertTrue(WorkHours.allowed(c,12000,50,0),"Exactly 50 permits overtime");h.assertTrue(!WorkHours.allowed(c,36000,20,0),"Consecutive night is mandatory rest");h.assertTrue(WorkHours.allowed(c,60000,20,0),"Third night can work");WorkHours.defaults(c,"守卫");h.assertTrue(c.willingness==45&&!WorkHours.allowed(c,84000,20,0),"Changing profession preserves previous night fatigue");var restored=CityEconomy.JSON.fromJson(CityEconomy.JSON.toJson(c),WorkHours.Config.class);h.assertTrue(restored.lastWorkedNight==c.lastWorkedNight,"Overtime persists restart");h.succeed();}
 @GameTest(template="empty") public static void meatPricesWeightsAndNoFish(GameTestHelper h){int[] counts=new int[5];for(int i=0;i<100;i++)counts[RuralMeat.type(i)]++;h.assertTrue(Arrays.equals(counts,new int[]{35,25,20,15,5}),"Exact category weights");double average=0;for(int i=0;i<5;i++)average+=counts[i]*RuralMeat.BUY[i]/100.0;h.assertTrue(Math.abs(average-16.5)<.0001&&RuralMeat.BUY[4]==16&&RuralMeat.SELL[4]==21,"Restored prices with rabbit -2");h.assertTrue(RuralMeat.RAW.length==5,"Only five meats, no fish or leather");h.succeed();}
 @GameTest(template="empty") public static void meatCapacityCookingAndReserves(GameTestHelper h){var stock=new RuralRules.Stock();stock.wheat=6;h.assertTrue(RuralMeat.put(List.of(stock),false,0,9)==4&&stock.free()==0,"Meat shares ten-portion storage");h.assertTrue(RuralMeat.cook(List.of(stock),2,4)==2&&stock.free()==0&&stock.raw[0]==2&&stock.cooked[0]==2,"Cooking 1:1 consumes budget and preserves capacity");var adult=CityTestsRural.person();var child=CityTestsRural.person();child.age=RuralRules.Age.CHILD;var baby=CityTestsRural.person();baby.age=RuralRules.Age.INFANT;var f=CityTestsRural.family(adult);f.members.add(child.id);f.members.add(baby.id);h.assertTrue(RuralMeat.reserve(f,Map.of(adult.id,adult,child.id,child,baby.id,baby))==4,"Adults and children reserve two; infants none");h.succeed();}
 @GameTest(template="empty") public static void spacingAndForestCriteria(GameTestHelper h){var p=BlockPos.ZERO;h.assertTrue(!HunterForest.separated(p,List.of(new BlockPos(63,200,0)),64)&&HunterForest.separated(p,List.of(new BlockPos(64,0,0)),64),"Horizontal 64 clearance, not vertical distance");h.assertTrue(HunterForest.dense(4,1)&&!HunterForest.dense(3,20)&&!HunterForest.dense(16,0),"Requires canopy and real logs");var far=new BlockPos(900000,0,900000);h.assertTrue(!h.getLevel().hasChunkAt(far)&&HunterForest.inspect(h.getLevel(),far.getX()>>4,far.getZ()>>4)==null&&!h.getLevel().hasChunkAt(far),"Forest sampling never loads missing chunk");h.succeed();}
 @GameTest(template="empty") public static void oldSchemaAndHunterPersistence(GameTestHelper h){var d=new RuralSettlement();d.state.schema=1;var p=CityTestsRural.person();var f=CityTestsRural.family(p);d.state.people.put(p.id,p);d.state.families.put(f.id,f);var old=d.save(new CompoundTag(),h.getLevel().registryAccess());var restored=RuralSettlement.load(old,h.getLevel().registryAccess());h.assertTrue(restored.state.schema==3&&restored.state.hours!=null&&restored.state.forest!=null,"Schema 1 migrates to 2");p.role=RuralRules.Role.HUNTER;p.huntingTicks=35980;p.huntingSpot=new BlockPos(7,8,9).asLong();var box=new RuralSettlement.Box();box.stock.raw[0]=4;d.state.boxes.put("x",box);var next=RuralSettlement.load(d.save(new CompoundTag(),h.getLevel().registryAccess()),h.getLevel().registryAccess());h.assertTrue(next.state.people.get(p.id).huntingTicks==35980&&next.state.boxes.get("x").stock.raw[0]==4,"Hunt progress and meat persist");h.succeed();}
 @GameTest(template="empty") public static void twelveHourUnloadedVillageConservation(GameTestHelper h){
  var server=h.getLevel().getServer();var economy=CityEconomy.get(server);var d=new RuralSettlement();var pos=new BlockPos(910000,64,910000);var city=new CityData.City(UUID.randomUUID(),UUID.randomUUID(),"隔离农村规则验证",h.getLevel().dimension().location().toString(),CityBounds.between(pos,pos.offset(63,7,31)));var plan=new CityMaintenance.Plan();for(int i=0;i<60;i++)plan.baseline.put(pos.offset(i,0,0).asLong(),CityMaintenance.encode(Blocks.WHEAT.defaultBlockState()));CityMaintenance.get(server).state.cities.put(city.id,plan);
  int initialWheat=0,initialBread=0;try{
   for(int group=0;group<6;group++){RuralRules.Family f=null;for(int i=0;i<2;i++){var p=CityTestsRural.person();p.trainedHours=10;p.role=i==1?RuralRules.Role.COOK:group<3?RuralRules.Role.FARMER:group<5?RuralRules.Role.HUNTER:RuralRules.Role.MERCHANT;if(f==null){f=CityTestsRural.family(p);f.city=city.id;d.state.families.put(f.id,f);}else{RuralRules.admit(f,p,d.state.people);p.spouse=f.members.getFirst();d.state.people.get(p.spouse).spouse=p.id;}d.state.people.put(p.id,p);city.residents.add(p.id);economy.state.accounts.put(CityEconomy.person(p.id),50L);var site=new RuralSettlement.Site();site.city=city.id;site.pos=pos.offset(group,1,i).asLong();site.worker=p.id;d.state.sites.put("site"+p.id,site);}
    for(int i=0;i<(group==5?15:6);i++){var box=new RuralSettlement.Box();box.city=city.id;box.pos=pos.offset(group,2,i).asLong();box.present=true;box.linked=true;box.stock.family=f.id;d.state.boxes.put("box"+group+"-"+i,box);}initialWheat+=RuralRules.put(d.stocks(f.id),false,40);initialBread+=RuralRules.put(d.stocks(f.id),true,group==5?30:12);
   }
   for(int minute=1;minute<=720;minute++){boolean work=(minute-1)%20<10;for(var p:d.state.people.values())p.workingTicks=work?1200:0;d.cycle(server,city,minute%30==0,minute%60==0);}
   long money=d.state.people.keySet().stream().mapToLong(id->economy.state.accounts.get(CityEconomy.person(id))).sum();int wheat=d.state.boxes.values().stream().mapToInt(b->b.stock.wheat).sum(),bread=d.state.boxes.values().stream().mapToInt(b->b.stock.bread).sum(),meat=d.state.boxes.values().stream().mapToInt(b->RuralMeat.total(List.of(b.stock))).sum();
   h.assertTrue(money==600,"Twelve-hour closed economy conserves all 600 silver");h.assertTrue(wheat==initialWheat+d.state.wheatProduced-d.state.breadProduced,"Wheat production and cooking conserve goods");h.assertTrue(bread==initialBread+d.state.breadProduced-d.state.foodEaten,"Bread production and eating conserve goods");h.assertTrue(meat==d.state.meatProduced-d.audit(city.id).meatEaten,"Meat retained/cooked/traded, never silently deleted");h.assertTrue(d.state.people.values().stream().filter(p->p.role==RuralRules.Role.HUNTER).allMatch(p->p.hunts==12),"12 hours with half-time work grants exactly 12 hunt trials");h.assertTrue(!h.getLevel().hasChunkAt(pos),"Village simulation needs no loaded NPCs/terrain");
  }finally{CityMaintenance.get(server).state.cities.remove(city.id);for(var id:d.state.people.keySet())economy.state.accounts.remove(CityEconomy.person(id));}h.succeed();
 }
}
